mapper.select:
SELECT , G.CD_NM AS GRADE_NM FROM TB_CUST C LEFT JOIN TB_COM_CODE G ON G.CD_GRP = 'CD001' AND G.CD = C.GRADE_CD WHERE C.STAT_CD = '01'
AND (C.CUST_NM LIKE '%' || #{searchKeyword} || '%' OR C.CUST_NO = #{searchKeyword})
AND C.GRADE_CD = #{gradeCd}
ORDER BY C.REG_DT DESC LIMIT #{firstIndex}, #{lastIndex}

mapper.insert:
INSERT INTO TB_CUST (
  CUST_NO, CUST_NM, RRNO, GRADE_CD, STAT_CD, HP_NO, REG_DT
) VALUES (
  #{custNo}, #{custNm}, #{rrno}, #{gradeCd}, #{statCd}, #{hpNo}, SYSDATE
)

INSERT INTO TB_CUST_HIST (
  CUST_NO, CUST_NM, GRADE_CD, STAT_CD, HIST_DT
) VALUES (
  #{custNo}, #{custNm}, #{gradeCd}, #{statCd}, SYSDATE
)
